ype":"text-editor"}],"isInner":false},{"id":"923ca3d","elType":"column","settings":{"_column_size":50,"_inline_size":29.635000000000002,"column_sticky_offset":50,"scroll_y":-80,"_inline_size_mobile":100},"elements":[{"id":"f59c87d","elType":"widget","settings":{"ids":[{"id":2773,"url":"https://demoes.aramis-co.ir/dgkala/wp-content/uploads/2021/11/asnaf-1-min.png"},{"id":2775,"url":"https://demoes.aramis-co.ir/dgkala/wp-content/uploads/2021/11/samandehi-1-min.png"},{"id":2774,"url":"https://demoes.aramis-co.ir/dgkala/wp-content/uploads/2021/11/namad-1-min.png"}],"spacing":"2","scroll_y":-80,"columns_mobile":{"unit":"px","size":3,"sizes":[]}},"elements":[],"widgetType":"wd_images_gallery"}],"isInner":false}],"isInner":false},{"id":"ea85cbe","elType":"section","settings":[],"elements":[{"id":"f07039f","elType":"column","settings":{"_column_size":100,"_inline_size":null,"column_sticky_offset":50,"scroll_y":-80,"_inline_size_mobile":100},"elements":[{"id":"6dd4b90","elType":"widget","settings":{"editor":"<p style="text-align: center;">استفاده از مطالب فروشگاه اینترنتی دیجی‌کالا فقط برای مقاصد غیرتجاری و با ذکر منبع بلامانع است. کلیه حقوق این سایت متعلق به شرکت نوآوران فن آوازه (فروشگاه آنلاین دیجی‌کالا) می‌باشد.</p>","text_color":"#81858B","typography_typography":"custom","typography_font_family":"iranyekan","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_font_weight":"400","wd_content_align":"center","scroll_y":-80},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false}]

item.content:encoded:
.dgkala .wd-btn-arrow
{
	opacity:1 !important;
	visibility: inherit !important;
}
/*
.more-products{display:none;}
*/
.productsuper .top-information.wd-fill , .productsuper .wd-buttons.wd-pos-r-t.color-scheme-light{display:none}
.wd-header-my-account.wd-tools-element.wd-event-hover.wd-with-username.wd-design-1.wd-account-style-icon.wd-tools-custom-icon.wd-with-overlay.whb-g7lf3ml70oj0jjb8zwlr{
	border: 1px solid #ccc!important;
	border-radius:8px
}
.haraj span{
	color:red !important;
}
.stories.carousel
{
	text-align:center;
}



.stories.snapgram .story.seen,.stories.carousel .story
{
	margin:0px 30px 4px 30px !important;
}
.stories.carousel .story>.item-link>.info .name
{
	font-weight:600 ;
}

